import tkinter as tk # Create the main window window = tk.Tk() window.title("Tkinter Geometry Managers") window.geometry("400x300") # Button using pack() frame1 = tk.Frame(window) frame1.pack() button1 = tk.Button(frame1, text="Pack Button") button1.pack() # Button using grid() frame2 = tk.Frame(window) frame2.pack() button2 = tk.Button(frame2, text="Grid Button") button2.grid(row=0, column=0, padx=20, pady=20) # Button using place() frame3 = tk.Frame(window, width=400, height=150) frame3.pack() button3 = tk.Button(frame3, text="Place Button") button3.place(x=150, y=50) # Run the GUI application window.mainloop()